-- Cria uma coluna curta para usar como título em tooltips no Power BI.
-- A coluna category original é mantida sem alterações.
ALTER TABLE amazon ADD COLUMN categoria_titulo TEXT;

UPDATE amazon
SET categoria_titulo = CASE category
    WHEN 'Computers&Accessories|Accessories&Peripherals|Cables&Accessories|Cables|USBCables' THEN 'USB Cables'
    WHEN 'Computers&Accessories|NetworkingDevices|NetworkAdapters|WirelessUSBAdapters' THEN 'Wireless USB Adapters'
    WHEN 'Electronics|HomeTheater,TV&Video|Accessories|Cables|HDMICables' THEN 'HDMI Cables'
